  OPTIONAL { ?s foaf:gender ?gender }
  OPTIONAL { ?s <http://dati.camera.it/ocd/rif_leg> ?rif_leg }
  FILTER(CONTAINS(LCASE(STR(?label)), LCASE("boschi")))
  FILTER(?rif_leg = <http://dati.camera.it/ocd/legislatura.rdf/repubblica_19>)
}
LIMIT 5

